export const getListMessengerChatsUrl = (slug: string,
    params?: ListMessengerChatsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${encodeURIComponent(String(slug))}/messengers/chats?${stringifiedParams}` : `/api/projects/${encodeURIComponent(String(slug))}/messengers/chats`
}

